"""Evaluate unchanged absorption-diffusion events through direct liquid sector ETFs."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import numpy as np,pandas as pd
SEED=20260829;COST=.0031
def bootstrap(values):
 x=np.asarray(values,float);rng=np.random.default_rng(SEED);means=[float(x[rng.integers(0,len(x),len(x))].mean()) for _ in range(2000)];return [float(np.quantile(means,.025)),float(np.quantile(means,.975))]
def run(waves_path,candidates_path,fund_basic,daily_path,adj_path,benchmark_path,events_path,out_json,out_md):
 waves=pd.read_csv(waves_path);waves=waves[waves.diffusion_date.notna()].copy();waves["signal_date"]=pd.to_datetime(waves.diffusion_date);candidates=pd.read_csv(candidates_path,dtype=str);candidates["list_date"]=pd.to_datetime(candidates.list_date,errors="coerce");candidates["delist_date"]=pd.to_datetime(candidates.delist_date,errors="coerce");daily=pd.read_parquet(daily_path);adj=pd.read_parquet(adj_path);daily.trade_date=pd.to_datetime(daily.trade_date.astype(str),format="mixed");adj.trade_date=pd.to_datetime(adj.trade_date.astype(str),format="mixed");prices=daily.merge(adj,on=["ts_code","trade_date"],how="inner");prices["adj_open"]=prices.open*prices.adj_factor;prices["adj_close"]=prices.close*prices.adj_factor;benchmark=pd.read_csv(benchmark_path);benchmark=benchmark[benchmark.asset=="equity"].copy();benchmark.trade_date=pd.to_datetime(benchmark.trade_date,format="mixed");benchmark=benchmark.set_index("trade_date").sort_index();records=[]
 for row in waves.itertuples(index=False):
  signal=pd.Timestamp(row.signal_date);pool=candidates[(candidates.industry==row.sector)&(candidates.list_date<=signal)&(candidates.delist_date.isna()|(candidates.delist_date>=signal))];choice=None;best=-np.inf
  for code in pool.ts_code.unique():
   history=prices[(prices.ts_code==code)&(prices.trade_date<signal)].sort_values("trade_date").tail(20)
   if len(history)>=10 and float(history.amount.mean())>=10000 and float(history.amount.mean())>best:choice=code;best=float(history.amount.mean())
  base={"event_id":f"{signal.date()}|{row.sector}","signal_date":signal.date().isoformat(),"industry":row.sector,"etf_code":choice,"status":"VALID","rejection_reason":""}
  future_dates=benchmark.index[benchmark.index>signal][:40]
  if choice is None or len(future_dates)<35:records.append({**base,"status":"INVALID","rejection_reason":"no_liquid_etf_or_horizon","observed_days":0});continue
  price=prices[prices.ts_code==choice].set_index("trade_date").sort_index();entry_date=future_dates[0]
  if entry_date not in price.index or float(price.at[entry_date,"adj_open"])<=0:records.append({**base,"status":"INVALID","rejection_reason":"missing_t1_open","observed_days":0});continue
  entry=float(price.at[entry_date,"adj_open"]);dates=[];returns=[];bench=[]
  for day in future_dates:
   if day not in price.index or day not in benchmark.index:break
   dates.append(day);returns.append(float(price.at[day,"adj_close"])/entry-1-COST);bench.append(float(benchmark.at[day,"adj_close"])/float(benchmark.at[entry_date,"adj_open"])-1)
  observed=len(returns);active=np.asarray(returns)-np.asarray(bench)
  def at(values,n):return float(values[n-1]) if len(values)>=n else None
  def extreme(values,kind):
   if not len(values):return (None,None,None)
   i=int(np.argmax(values) if kind=="max" else np.argmin(values));return float(values[i]),i+1,dates[i].date().isoformat()
  maxr,maxrd,maxrdate=extreme(returns,"max");minr,minrd,minrdate=extreme(returns,"min");maxa,maxad,maxadate=extreme(active,"max");mina,minad,minadate=extreme(active,"min");records.append({**base,"entry_date":entry_date.date().isoformat(),"avg_amount20":best,"observed_days":observed,"return_d30":at(returns,30),"return_d35":at(returns,35),"return_d40":at(returns,40),"active_d30":at(active,30),"active_d35":at(active,35),"active_d40":at(active,40),"max_return_40":maxr,"max_return_day":maxrd,"max_return_date":maxrdate,"min_return_40":minr,"min_return_day":minrd,"min_return_date":minrdate,"max_active_40":maxa,"max_active_day":maxad,"max_active_date":maxadate,"min_active_40":mina,"min_active_day":minad,"min_active_date":minadate,"days_outperform_hs300_40":int((active>0).sum()),"outperform_ratio_40":float((active>0).mean()) if observed else None,"success_d35":bool(observed>=35 and returns[34]>0 and active[34]>=.02)})
 events=pd.DataFrame(records);events.to_csv(events_path,index=False);complete=events[(events.status=="VALID")&events.active_d35.notna()].copy();complete["year"]=pd.to_datetime(complete.signal_date).dt.year;trim=complete[complete.active_d35<=complete.active_d35.quantile(.95)] if len(complete) else complete;ci=bootstrap(complete.active_d35) if len(complete) else [np.nan,np.nan];folds={name:{"count":len(x),"mean_active35":float(x.active_d35.mean()) if len(x) else 0.0,"success_rate":float(x.success_d35.mean()) if len(x) else 0.0} for name,a,b in (("2018-2022",2018,2022),("2023-2024",2023,2024),("2025",2025,2025)) for x in [complete[complete.year.between(a,b)]]};summary={"source_events":len(waves),"mapped_events":int(events.etf_code.notna().sum()),"complete35":len(complete),"mapping_rate":float(events.etf_code.notna().mean()) if len(events) else 0.0,"absolute_positive_rate":float((complete.return_d35>0).mean()) if len(complete) else 0.0,"outperform_rate":float((complete.active_d35>0).mean()) if len(complete) else 0.0,"success_rate":float(complete.success_d35.mean()) if len(complete) else 0.0,"mean_active35":float(complete.active_d35.mean()) if len(complete) else 0.0,"median_active30":float(complete.active_d30.median()) if len(complete) else 0.0,"median_active35":float(complete.active_d35.median()) if len(complete) else 0.0,"median_active40":float(complete.active_d40.median()) if len(complete) else 0.0,"bootstrap95":ci,"trim_top5_mean":float(trim.active_d35.mean()) if len(trim) else 0.0,"folds":folds,"industries":{i:{"count":len(x),"success_rate":float(x.success_d35.mean()),"median_active35":float(x.active_d35.median())} for i,x in complete.groupby("industry")}};checks={"count":len(complete)>=30,"mapping":summary["mapping_rate"]>=.5,"absolute":summary["absolute_positive_rate"]>=.6,"outperform":summary["outperform_rate"]>=.6,"success":summary["success_rate"]>=.55,"median":summary["median_active35"]>=.02,"bootstrap":ci[0]>0,"horizons":min(summary["median_active30"],summary["median_active35"],summary["median_active40"])>0,"trim":summary["trim_top5_mean"]>0,"folds":sum(x["mean_active35"]>0 for x in folds.values())>=2,"holdout":folds["2025"]["count"]>0 and folds["2025"]["success_rate"]>.5 and folds["2025"]["mean_active35"]>0};verdict="GO" if all(checks.values()) else ("MARGINAL" if summary["mean_active35"]>0 else "NO-GO");payload={"study":"a-share-sector-etf-execution-v1","summary":summary,"decision":{"verdict":verdict,"checks":checks},"events":events_path,"limitations":["ETF benchmark may not exactly match SW L1 industry","historical ETF availability limits coverage","research-grade provider data only"]};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");lines=["# A股行业ETF执行结果","",f"- verdict: **{verdict}**",f"- source/mapped/complete35: {len(waves)}/{summary['mapped_events']}/{len(complete)}",f"- success/outperform/median active35: {summary['success_rate']:.2%}/{summary['outperform_rate']:.2%}/{summary['median_active35']:.2%}","","|行业|事件|成功率|active中位数|","|---|---:|---:|---:|"]
 for industry,value in sorted(summary["industries"].items()):lines.append(f"|{industry}|{value['count']}|{value['success_rate']:.2%}|{value['median_active35']:.2%}|")
 Path(out_md).write_text("\n".join(lines)+"\n");return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--waves",default="overall/a-share-turnover-absorption-waves.csv");p.add_argument("--candidates",default="overall/a-share-sector-etf-candidates.csv");p.add_argument("--fund-basic",default="overall/a-share-fund-basic.csv");p.add_argument("--daily",default="overall/a-share-sector-etf-raw-v2/fund_daily.parquet");p.add_argument("--adj",default="overall/a-share-sector-etf-raw-v2/fund_adj.parquet");p.add_argument("--benchmark",default="overall/a-share-equity-etf-daily-current.csv");p.add_argument("--events",default="overall/a-share-sector-etf-execution-events.csv");p.add_argument("--out-json",default="overall/a-share-sector-etf-execution.json");p.add_argument("--out-md",default="overall/a-share-sector-etf-execution.md");a=p.parse_args(argv);payload=run(a.waves,a.candidates,a.fund_basic,a.daily,a.adj,a.benchmark,a.events,a.out_json,a.out_md);print(json.dumps(payload["summary"],ensure_ascii=False,indent=2));return 0
if __name__=="__main__":raise SystemExit(main())
